import React, { useState, useMemo, useEffect, useCallback } from "react";
import {
  Box,
  Typography,
  IconButton,
  Tooltip,
  alpha,
  useTheme,
} from "@mui/material";
import {
  Visibility as ViewIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  VideoLibrary as VideoIcon,
  PlayCircleOutline as PlayIcon,
} from "@mui/icons-material";
import DataTable from "../../../components/DataTable";
import DetailsModal from "../../../components/DetailsModal";
import ConfirmationModal from "../../../components/ConfirmationModal";
import AppTutorialModal from "../../../components/page_components/AppTutorialModal";
import StatusDropdown from "../../../components/StatusDropdown";
import { toast } from "react-hot-toast";
import { useSelector } from "react-redux";
import { mapAppTutorialExport } from "../../../utils/exportMappers";
import { extractExportList, performExport } from "../../../utils/exportHelpers";
import dayjs from "dayjs";
import ImageView from "../../../components/ImageView";
import VideoView from "../../../components/VideoView";

const BASE_URL = process.env.REACT_APP_API_BASE_URL || 'https://api.fitness-savage.mtechub.com/api/v1';

const AppTutorial = () => {
  const theme = useTheme();
  const [tutorials, setTutorials] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [totalCount, setTotalCount] = useState(0);
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(5);
  const [orderBy, setOrderBy] = useState("created_at");
  const [order, setOrder] = useState("desc");
  const [searchTerm, setSearchTerm] = useState("");
  const [isExporting, setIsExporting] = useState(false);

  const [openViewModal, setOpenViewModal] = useState(false);
  const [openDeleteModal, setOpenDeleteModal] = useState(false);
  const [openAddEditModal, setOpenAddEditModal] = useState(false);
  const [selectedTutorial, setSelectedTutorial] = useState(null);
  const [tutorialToDelete, setTutorialToDelete] = useState(null);
  const [tutorialToEdit, setTutorialToEdit] = useState(null);
  const [isSaving, setIsSaving] = useState(false);
  const [updatingStatusId, setUpdatingStatusId] = useState(null);

  const token = useSelector((state) => state.auth.token);

  const fetchTutorials = useCallback(async () => {
    if (!token) return;
    setIsLoading(true);
    try {
      const queryParams = new URLSearchParams({
        page: page + 1,
        limit: rowsPerPage,
        sort_by: orderBy,
        sort_order: order,
        q: searchTerm,
      });

      const response = await fetch(`${BASE_URL}/admin/demo-videos?${queryParams.toString()}`, {
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });

      const json = await response.json();
      if (!response.ok || json.error) {
        toast.error(json.message || "Failed to fetch tutorials");
        setTutorials([]);
        setTotalCount(0);
        return;
      }
      
      setTutorials(json.data?.videos || []);
      setTotalCount(json.data?.pagination?.total || 0);
    } catch (error) {
      console.error("Fetch error:", error);
      toast.error("Something went wrong while fetching tutorials");
    } finally {
      setIsLoading(false);
    }
  }, [token, page, rowsPerPage, orderBy, order, searchTerm]);

  useEffect(() => {
    fetchTutorials();
  }, [fetchTutorials]);

  const handleStatusChange = async (id, newStatus) => {
    if (!token) return;
    setUpdatingStatusId(id);
    try {
      const response = await fetch(`${BASE_URL}/admin/demo-videos/${id}`, {
        method: "PUT",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({ is_active: newStatus === 'active' }),
      });
      const json = await response.json();
      if (!response.ok || json.error) {
        toast.error(json.message || "Failed to update status");
      } else {
        toast.success("Status updated successfully");
        // Backend enforces a single active tutorial: activating one deactivates
        // the rest, so refetch to reflect the authoritative state.
        fetchTutorials();
      }
    } catch (err) {
      toast.error("Connection error while updating status");
    } finally {
      setUpdatingStatusId(null);
    }
  };

  const handleExport = useCallback(async (dates, format) => {
    if (!token) return;
    const toastId = toast.loading(`Exporting tutorials as ${format.toUpperCase()}...`);
    setIsExporting(true);
    try {
      const queryParams = new URLSearchParams({
        q: searchTerm,
        sort_by: orderBy,
        sort_order: order,
        not_pagination: 'true',
        start_date: dates.startDate.format('YYYY-MM-DD'),
        end_date: dates.endDate.format('YYYY-MM-DD'),
      });

      const res = await fetch(`${BASE_URL}/admin/demo-videos?${queryParams.toString()}`, {
        method: 'GET',
        headers: {
          Authorization: `Bearer ${token}`,
          'Content-Type': 'application/json',
        },
      });

      const json = await res.json();
      if (!res.ok || json.error) {
        throw new Error(json.message || 'Failed to fetch videos for export');
      }

      const items = extractExportList(json, 'videos');
      const filename = `App_Tutorials_${dates.startDate.format('YYYYMMDD')}_to_${dates.endDate.format('YYYYMMDD')}`;

      await performExport({
        items,
        mapper: mapAppTutorialExport,
        format,
        filename,
        sheetName: 'Tutorials',
        entityName: 'tutorials',
        toastId,
      });
    } catch (err) {
      console.error('Export error:', err);
      toast.error(err.message || 'Export error', { id: toastId });
    } finally {
      setIsExporting(false);
    }
  }, [token, searchTerm, orderBy, order]);

  const handleSortChange = (property) => {
    const isAsc = orderBy === property && order === "asc";
    setOrder(isAsc ? "desc" : "asc");
    setOrderBy(property);
    setPage(0);
  };

  const handleViewDetails = (tutorial) => {
    setSelectedTutorial(tutorial);
    setOpenViewModal(true);
  };

  const handleAddClick = () => {
    setTutorialToEdit(null);
    setOpenAddEditModal(true);
  };

  const handleEditClick = (tutorial) => {
    setTutorialToEdit(tutorial);
    setOpenAddEditModal(true);
  };

  const handleDeleteClick = (tutorial) => {
    setTutorialToDelete(tutorial);
    setOpenDeleteModal(true);
  };

  const handleConfirmDelete = async () => {
    if (!tutorialToDelete || !token) return;
    const toastId = toast.loading("Deleting tutorial...");
    try {
      const response = await fetch(`${BASE_URL}/admin/demo-videos/${tutorialToDelete.id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success("Deleted Successfully!", { id: toastId });
        fetchTutorials();
      } else {
        toast.error(result.message || "Delete failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Server error", { id: toastId });
    } finally {
      setOpenDeleteModal(false);
      setTutorialToDelete(null);
    }
  };

  const handleSaveTutorial = async (formData) => {
    if (!token) return;
    setIsSaving(true);
    const toastId = toast.loading(`${tutorialToEdit ? 'Updating' : 'Adding'} tutorial...`);
    try {
      const url = tutorialToEdit 
        ? `${BASE_URL}/admin/demo-videos/${tutorialToEdit.id}`
        : `${BASE_URL}/admin/demo-videos`;
      
      const response = await fetch(url, {
        method: tutorialToEdit ? "PUT" : "POST",
        headers: {
          Authorization: `Bearer ${token}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify(formData),
      });

      const result = await response.json();
      if (response.ok && !result.error) {
        toast.success(`Tutorial ${tutorialToEdit ? 'Updated' : 'Added'} Successfully!`, { id: toastId });
        setOpenAddEditModal(false);
        setTutorialToEdit(null);
        fetchTutorials();
      } else {
        toast.error(result.message || "Save failed", { id: toastId });
      }
    } catch (error) {
      toast.error("Internal server error", { id: toastId });
    } finally {
      setIsSaving(false);
    }
  };

  const columns = [
    {
      id: "title",
      label: "Tutorial Info",
      sortable: true,
      render: (row) => (
        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
          <Box
            sx={{
              width: 50,
              height: 50,
              borderRadius: "12px",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              bgcolor: alpha(theme.palette.primary.main, 0.1),
              overflow: "hidden",
              border: "1px solid rgba(255,255,255,0.05)"
            }}
          >
            <ImageView
              src={row.image_url || row.thumbnail_image}
              alt={row.title}
              sx={{ width: "100%", height: "100%", objectFit: "cover" }}
            />
          </Box>
          <Box>
            <Typography sx={{ color: "#FFFFFF", fontWeight: 600, fontSize: "0.875rem", fontFamily: "'Montserrat', sans-serif" }}>
              {row.title}
            </Typography>
            <Typography sx={{ color: "#8B8D97", fontSize: "0.75rem", mt: 0.5, fontFamily: "'Montserrat', sans-serif" }}>
              ID: {row.id}
            </Typography>
          </Box>
        </Box>
      ),
    },
    {
        id: 'is_active',
        label: 'Status',
        sortable: true,
        render: (row) => (
            <StatusDropdown
                status={row.is_active ? 'active' : 'inactive'}
                options={[
                    { label: 'Active', value: 'active', color: '#4CC66E' },
                    { label: 'Inactive', value: 'inactive', color: '#FF5050' },
                ]}
                onStatusChange={(val) => handleStatusChange(row.id, val)}
                isLoading={updatingStatusId === row.id}
            />
        )
    },
    {
      id: "created_at",
      label: "Date Created",
      sortable: true,
      render: (row) => (
        <Typography sx={{ color: "#8B8D97", fontSize: "0.875rem", fontFamily: "'Montserrat', sans-serif" }}>
          {new Date(row.created_at).toLocaleDateString()}
        </Typography>
      ),
    },
    {
      id: "actions",
      label: "Actions",
      render: (row) => (
        <Box sx={{ display: "flex", gap: 1 }}>
          <Tooltip title="View Tutorial">
            <IconButton
              size="small"
              onClick={() => handleViewDetails(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <ViewIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Edit">
            <IconButton
              size="small"
              onClick={() => handleEditClick(row)}
              sx={{
                color: "#9F6EDA",
                bgcolor: alpha("#9F6EDA", 0.1),
                "&:hover": { bgcolor: alpha("#9F6EDA", 0.2) },
              }}
            >
              <EditIcon fontSize="small" />
            </IconButton>
          </Tooltip>
          <Tooltip title="Delete">
            <IconButton
              size="small"
              onClick={() => handleDeleteClick(row)}
              sx={{
                color: "#FF5050",
                bgcolor: alpha("#FF5050", 0.1),
                "&:hover": { bgcolor: alpha("#FF5050", 0.2) },
              }}
            >
              <DeleteIcon fontSize="small" />
            </IconButton>
          </Tooltip>
        </Box>
      ),
    },
  ];

  const tutorialDetailsData = useMemo(() => {
    if (!selectedTutorial) return [];
    return [
      { label: "Title", value: selectedTutorial.title },
      { label: "Description", value: selectedTutorial.description || "N/A" },
      { label: "Video URL", value: selectedTutorial.video_url },
      { label: "Status", value: selectedTutorial.is_active ? "Active" : "Inactive" },
      {
        label: "Created At",
        value: new Date(selectedTutorial.created_at).toLocaleString(),
      },
      {
        label: "Last Updated",
        value: new Date(selectedTutorial.updated_at).toLocaleString(),
      },
    ];
  }, [selectedTutorial]);

  return (
    <Box sx={{ p: { xs: 1, md: 3 } }}>
      <DataTable
        title="App Tutorials"
        columns={columns}
        data={tutorials}
        isLoading={isLoading}
        onAddClick={handleAddClick}
        addLabel="Add Tutorial"
        onExport={handleExport}
        isExporting={isExporting}
        searchTerm={searchTerm}
        onSearchChange={(val) => {
          setSearchTerm(val);
          setPage(0);
        }}
        orderBy={orderBy}
        order={order}
        onSortChange={handleSortChange}
        pagination={{
          page: page,
          rowsPerPage: rowsPerPage,
          totalCount: totalCount,
          onPageChange: (_, newPage) => setPage(newPage),
          onRowsPerPageChange: (e) => {
            setRowsPerPage(parseInt(e.target.value, 10));
            setPage(0);
          },
        }}
        emptyTitle="No tutorials found"
       
      />

      {selectedTutorial && (
        <DetailsModal
          open={openViewModal}
          onClose={() => setOpenViewModal(false)}
          title="Tutorial Details"
          data={tutorialDetailsData}
          maxWidth="sm"
        >
          <Box sx={{ mt: 3, width: '100%' }}>
            <Typography variant="subtitle2" sx={{ color: '#fff', mb: 1.5, fontWeight: 700, fontFamily: "'Montserrat', sans-serif" }}>
                Video Preview
            </Typography>
            <Box sx={{
                width: '100%',
                aspectRatio: '16/9',
                borderRadius: '16px',
                overflow: 'hidden',
                bgcolor: '#000',
                border: '1px solid rgba(255,255,255,0.1)'
            }}>
                <VideoView
                    src={selectedTutorial.video_url || selectedTutorial.video}
                    poster={selectedTutorial.image_url || selectedTutorial.thumbnail_image}
                    sx={{ width: '100%', height: '100%', objectFit: 'contain' }}
                />
            </Box>
          </Box>
        </DetailsModal>
      )}

      <AppTutorialModal
        open={openAddEditModal}
        onClose={() => setOpenAddEditModal(false)}
        onSubmit={handleSaveTutorial}
        initialData={tutorialToEdit}
        loading={isSaving}
      />

      <ConfirmationModal
        open={openDeleteModal}
        onClose={() => setOpenDeleteModal(false)}
        onConfirm={handleConfirmDelete}
        title="Delete Tutorial?"
        message={`Are you sure you want to delete "${tutorialToDelete?.title}"? This cannot be undone.`}
        confirmText="Delete"
        confirmColor="error"
      />
    </Box>
  );
};

export default AppTutorial;
