import React, { useState, useEffect } from 'react';
import { 
    Box, 
    TextField, 
    Button, 
    useTheme,
    Typography,
    alpha,
    InputLabel
} from '@mui/material';
import { 
    VideoLibrary as VideoIcon, 
    InsertPhoto as PhotoIcon, 
    Title as TitleIcon, 
    Description as DescIcon 
} from '@mui/icons-material';
import BaseModal from '../BaseModal';
import FileUpload from '../FileUpload';

const AppTutorialModal = ({ 
    open, 
    onClose, 
    onSubmit, 
    initialData = null, 
    loading = false 
}) => {
    const isEdit = !!initialData;
    const theme = useTheme();

    const [formData, setFormData] = useState({
        title: '',
        description: '',
        video_url: '',
        image_url: ''
    });

    useEffect(() => {
        if (open) {
            if (initialData) {
                setFormData({
                    title: initialData.title || '',
                    description: initialData.description || '',
                    video_url: initialData.video_url || initialData.video || '',
                    image_url: initialData.image_url || initialData.thumbnail_image || ''
                });
            } else {
                setFormData({
                    title: '',
                    description: '',
                    video_url: '',
                    image_url: ''
                });
            }
        }
    }, [open, initialData]);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ 
            ...prev, 
            [name]: value 
        }));
    };

    const handleSubmit = (e) => {
        e.preventDefault();
        onSubmit(formData);
    };

    const actions = (
        <Box sx={{ display: 'flex', gap: 2, width: '100%' }}>
            <Button
                fullWidth
                variant="outlined"
                onClick={onClose}
                disabled={loading}
                sx={{ 
                    color: 'text.secondary', 
                    boxShadow: 'none',
                    borderColor: 'rgba(255, 255, 255, 0.1)',
                    '&:hover': {
                        borderColor: 'text.secondary',
                        bgcolor: 'rgba(255, 255, 255, 0.05)'
                    }
                }}
            >
                Cancel
            </Button>
            <Button
                fullWidth
                variant="contained"
                onClick={handleSubmit}
                disabled={loading || !formData.title || !formData.video_url || !formData.image_url}
                sx={{ 
                    fontWeight: 700,
                    bgcolor: '#4CC66E',
                    '&:hover': { bgcolor: '#3EB05D' },
                    '&.Mui-disabled': {
                        bgcolor: alpha('#4CC66E', 0.5),
                        color: 'rgba(255, 255, 255, 0.5)'
                    }
                }}
            >
                {loading ? 'Processing...' : (isEdit ? 'Update Tutorial' : 'Add Tutorial')}
            </Button>
        </Box>
    );

    return (
        <BaseModal
            open={open}
            onClose={onClose}
            title={isEdit ? 'Edit App Tutorial' : 'Add New Tutorial'}
            maxWidth="sm"
            actions={actions}
        >
            <Box 
                component="form" 
                onSubmit={handleSubmit} 
                sx={{ 
                    pt: 1,
                    display: 'flex',
                    flexDirection: 'column',
                    gap: 3,
                    width: '100%',
                }}
            >
                <Box>
                    <Typography 
                        sx={{ 
                            mb: 1, 
                            color: '#8B8D97', 
                            fontWeight: 700, 
                            fontSize: '0.75rem', 
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        Tutorial Title
                    </Typography>
                    <TextField
                        fullWidth
                        name="title"
                        value={formData.title}
                        onChange={handleChange}
                        required
                        placeholder="e.g. How to use Savage Mushroom"
                    />
                </Box>
                
                <Box>
                    <Typography 
                        sx={{ 
                            mb: 1, 
                            color: '#8B8D97', 
                            fontWeight: 700, 
                            fontSize: '0.75rem', 
                            textTransform: 'uppercase',
                            letterSpacing: '0.05em'
                        }}
                    >
                        Short Description
                    </Typography>
                    <TextField
                        fullWidth
                        name="description"
                        value={formData.description}
                        onChange={handleChange}
                        multiline
                        rows={3}
                        placeholder="Briefly describe what this tutorial covers"
                    />
                </Box>

                <Box sx={{ display: 'flex', gap: 3, flexDirection: 'column' }}>
                    <Box sx={{ flex: 1 }}>
                        <Typography 
                            sx={{ 
                                color: '#8B8D97', 
                                fontWeight: 700, 
                                mb: 1, 
                                fontSize: '0.75rem',
                                textTransform: 'uppercase',
                                letterSpacing: '0.05em'
                            }}
                        >
                            Tutorial Video
                        </Typography>
                        <FileUpload 
                            folderName="app_tutorials"
                            accept={{ 'video/*': [] }}
                            maxSizeMB={100}
                            helperText="MP4, WebM (max 100MB)"
                            existingImageUrl={formData.video_url}
                            onUploadSuccess={(url) => setFormData(prev => ({ ...prev, video_url: url }))}
                            onRemove={() => setFormData(prev => ({ ...prev, video_url: '' }))}
                        />
                    </Box>

                    <Box sx={{ flex: 1 }}>
                        <Typography 
                            sx={{ 
                                color: '#8B8D97', 
                                fontWeight: 700, 
                                mb: 1, 
                                fontSize: '0.75rem',
                                textTransform: 'uppercase',
                                letterSpacing: '0.05em'
                            }}
                        >
                            Thumbnail Image
                        </Typography>
                        <FileUpload 
                            folderName="app_tutorial_thumbnails"
                            maxSizeMB={5}
                            helperText="PNG, JPG or WEBP (max 5MB)"
                            existingImageUrl={formData.image_url}
                            onUploadSuccess={(url) => setFormData(prev => ({ ...prev, image_url: url }))}
                            onRemove={() => setFormData(prev => ({ ...prev, image_url: '' }))}
                        />
                    </Box>
                </Box>
            </Box>
        </BaseModal>
    );
};

export default AppTutorialModal;
